export const techniques=[
 t('yarn','糸の持ち方','はじめの準備','糸を少しずつ送り出して、編み目の大きさをそろえる準備です。','すべてのかぎ針編みの最初に。',['利き手と反対の手で糸を持ち、人差し指に糸をかけます。','親指と中指で編み始めの結び目をそっと挟みます。','糸が滑るか確かめて、楽な位置に調整します。'],'指に強く巻くと糸が動きません。締めつけず、力を抜きましょう。',['basics']),
 t('hook','針の持ち方','はじめの準備','かぎ針を楽に動かせる持ち方を探しましょう。','編み始める前の姿勢づくり。',['鉛筆を持つように、針の平らな部分を持ちます。','針先が自分の方に少し向くようにします。','糸をすくう動きを、手首に力を入れず試します。'],'握りすぎると手が疲れます。ナイフのような持ち方でも、楽なら大丈夫です。',['basics']),
 t('start','作り目','はじめの準備','ここでは、鎖編みを始めるための最初の輪を作ります。','平らな編み地を編み始めるとき。',['糸端を10〜15cmほど残して輪を作ります。','輪の中に、糸玉につながる糸を引き出します。','引き出した輪に針を入れ、針が動く程度に締めます。'],'最初の輪は鎖編みの目数に数えません。輪を小さく締めすぎないように。',['chain']),
 t('chain','鎖編み','基本の編み方','糸を輪に通して、鎖のようにつなげる編み方です。','土台の作り目や、透かし模様のすき間に。',['作り目の輪を針にかけます。','糸玉側の糸を針にかけます。','針にかかっていた輪から、その糸を引き抜きます。','同じ動きを繰り返します。針にある輪は目数に含めません。'],'きつく編むと次の段で針が入りません。輪の大きさをそろえ、軽く糸を送りましょう。',['chain']),
 t('single','細編み','基本の編み方','低く、しっかりした編み地を作る基本の編み方です。','コースターや小物、縁を整えるとき。',['編み入れる目に針を入れます。','糸をかけて引き出します。針に輪が2つ残ります。','もう一度糸をかけ、2つの輪を一度に引き抜きます。'],'段の最後の目を見落とすと幅が狭くなります。両端にマーカーをつけましょう。',['single']),
 t('half','中長編み','基本の編み方','細編みと長編みの中間の高さで、ふっくら編めます。','厚みがほしい小物やマフラーに。',['糸を針に1回かけてから、目に針を入れます。','糸をかけて引き出します。針の輪は3つです。','もう一度糸をかけ、3つの輪をまとめて引き抜きます。'],'糸をかけ忘れると細編みになります。針を入れる前に確認しましょう。',['half']),
 t('double','長編み','基本の編み方','背の高い編み目で、軽やかな編み地を作ります。','方眼編みやモチーフ、ショールなどに。',['糸を針に1回かけて、目に針を入れます。','糸をかけて引き出します。針に輪が3つあります。','糸をかけ、手前の2つの輪を引き抜きます。','再び糸をかけ、残る2つの輪を引き抜きます。'],'一度に全部の輪を抜かず、2つずつ抜きます。立ち上がりの数え方はレシピに合わせます。',['double']),
 t('slip','引き抜き編み','基本の編み方','ほとんど高さを出さず、編み目どうしをつなぎます。','輪を閉じるときや、つなぎ目に。',['つなぎたい目に針を入れます。','糸をかけます。','その糸を、編み目と針にある輪の両方から一度に引き抜きます。'],'きつく引くとつなぎ目が縮みます。周りと同じ力加減で。',['basics']),
 t('increase','増し目','形をつくる','同じ目に2目以上編んで、編み地を広げます。','丸い底や、幅を広げたいところに。',['指定された目に細編みを1目編みます。','同じ目にもう1目、細編みを編みます。','1つの目が2つになったことを数えて確かめます。'],'すべての目で増やすわけではありません。増やす位置と回数はレシピで確認します。',['single']),
 t('decrease','減らし目','形をつくる','隣り合う目をまとめて、編み地を狭くします。','口をすぼめたり、丸みを作るときに。',['1つ目の目から糸を引き出し、針に残します。','次の目からも糸を引き出します。針の輪は3つです。','糸をかけ、3つの輪をまとめて引き抜きます（細編み2目一度）。'],'目を飛ばすだけだと穴が開きます。2つの目をまとめて編みましょう。',['single']),
 t('net','ネット編み','模様の編み方','鎖編みのアーチを細編みで留め、網目を作ります。','軽いバッグや透かし模様に。',['レシピで指定された数の鎖編みを編みます。','指定された位置に細編みを編んで留めます。','次の段では、前の段のアーチに細編みを編み入れます。'],'鎖の数が変わると網目がばらつきます。最初は同じ数を声に出して数えましょう。',['net','chain','single']),
 t('filet','方眼編み','模様の編み方','鎖編みと長編みを組み合わせ、四角いすき間を作ります。','透かし模様のカバーや、レース小物に。',['小さな練習用の土台を鎖編みで作ります。','長編み、鎖編み、土台の目を飛ばして長編み、の順で方眼を作ります。','次の段は長編みの上に長編みを重ねます。鎖の数と飛ばす目数は同じレシピに従います。'],'段の端で方眼が増減しやすいので、毎段のマス数を確認しましょう。',['double','chain']),
 t('finish','糸始末','仕上げ','残った糸端を編み地に通して、ほどけにくくします。','編み終わりや、糸を替えた部分に。',['糸端を10〜15cm残して切り、最後の輪から抜きます。','とじ針に糸端を通します。','裏側の編み目に数cmくぐらせ、向きを変えてさらに通します。','表に響かないか確かめて、余った糸を切ります。'],'短く切りすぎると糸端が抜けます。編み地を軽く伸ばしてから切りましょう。',['finish'])
];
